using Bank.Payments.Domain.Model;
using Bank.Payments.Domain.Port;
using Bank.Payments.Infrastructure;

namespace Bank.Payments.Adapters.Out.Sql;

/// <summary>ADO.NET adapter of the ServiceRepository port.</summary>
public sealed class SqlServiceRepository(Db db) : ServiceRepository
{
    public ServiceCatalog? FindByCode(string? servicio)
    {
        using var command = db.Command(
            "SELECT srv_codigo, srv_tarifa FROM ad_servicio WHERE srv_codigo = @servicio");
        command.Parameters.AddWithValue("@servicio", (object?)servicio ?? DBNull.Value);
        using var reader = command.ExecuteReader();
        if (!reader.Read())
        {
            return null;
        }

        return new ServiceCatalog(
            reader.IsDBNull(0) ? null : reader.GetString(0),
            reader.IsDBNull(1) ? null : reader.GetDecimal(1));
    }
}
